\begin{theorem}\label{strongmg} 
For any mixed graph $G=(V,E,A)$ and positive integer $k$, $(-1)^{|V|} \widehat{\chi}_G(-k)$ equals the number of $k$-colorings of $G$, each counted with multiplicity equal to the number of compatible acyclic orientations of~$G$.
\end{theorem}

\begin{theorem}\label{main}
For any acyclic mixed graph $G=(V,E,A)$ and positive integer $k$, $(-1)^{|V|} {\chi}_G(-k)$ equals the number of $k$-colorings of $G$, each counted with multiplicity equal to the number of intercompatible acyclic orientations of~$G$.
\end{theorem}

\begin{prop} 
(Example 3.7 of \cite{bocker1998})
If $T$ is a binary tree such that the interior edges of $T$ are labeled $E=\{e_1,...,e_{n-3}\}$, and $Q$ is a system of quartet trees such that each $q_i \in Q$ distinguishes a unique edge $e_i$ in $T$ with \[|supp(q_i)\backslash \bigcup_{j<i} supp(q_j)|= 1\] for $i=2,...,n-3$, then $Q$ is definitive. 
\label{bocker2}\end{prop}

\begin{thm} 
 Every linked system of quartet trees is definitive.
\label{hierarchy} 
\end{thm}

\begin{thm}
The minimal number $k(n)$ such that every collection of quartets $S$  with $|S| \geq k$ is decisive is greater than {n \choose 4} - (n-3).
\label{ge}\end{thm}

\begin{thm}
If $q_i$ and $q_j$ are linked quartet trees, then  the associated  vines $v(q_i)$ and $v(q_j)$ are linked.
\label{linkedquartets}\end{thm}

\begin{thm}
For any binary phylogenetic tree $T$ on a taxon set $X$, the system $Q_T$ of all quartet trees displayed by $T$ contains a meshed system. 
\label{number}\end{thm}

\begin{thm}
\label{thm:big}
The  number $k(n)={n \choose 4} - (n-4)$ is the smallest number such that every collection of quartets $\mathcal{S}$ on a taxon set $X=[n]$ such that  $\mathcal{S} \geq k$ is decisive.
\label{minimal}\end{thm}

\begin{thm}
The probability $p(X,k)$ that an arbitrary collection of $k$ quartets is decisive has the property 
\[p(X,k) \geq \frac{\sum\limits_{i=1}^{n-3} (-1)^{i+1}{{n-3} \choose i}{{|Q_T|-i(n-3)} \choose {|Q_T|-k}}}{{|Q_T| \choose {k}}}.\]
\end{thm}

