\begin{claim} \label{clmmeasurables}
  Suppose that $\aleph_0<\kappa<\lambda$ and both $\kappa$ and $\lambda$ are measurable.
  Then ${\rm Gal}(\mathscr{U},\lambda,\lambda)$ holds whenever $\mathscr{U}$ is a normal ultrafilter over $\kappa$.
\end{claim}

